// ============================================================
const NORMALIZE_NODE = 'Normalize Lead Details';
const CONFIG_NODE    = 'Set: Brokerage Configuration';
// ============================================================

const lead   = $(NORMALIZE_NODE).first().json;
const config = $(CONFIG_NODE).first().json;
const allItems = $input.all();

// Extract Gemini output
let rawText = '';
for (const item of allItems) {
  const text = item.json?.content?.parts?.[0]?.text
    || item.json?.candidates?.[0]?.content?.parts?.[0]?.text
    || item.json?.output || '';
  if (text && text.includes('score')) {
    rawText = text;
    break;
  }
}

const cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    score: 'Warm',
    reasoning: 'AI parsing failed — defaulting to Warm.',
    recommendedSpeciality: 'General',
    urgencyNote: 'Follow up within 24 hours.',
    personalisation: `Hi ${lead.leadName}, thank you for reaching out — I would love to help you.`
  };
}

// Parse agents from config
let agents = [];
try {
  agents = JSON.parse(config.AGENTS_JSON || '[]');
} catch (e) {
  agents = [];
}

// Agent selection — speciality match + load balance
let pool = agents.filter(a =>
  a.speciality === parsed.recommendedSpeciality &&
  a.status === 'Available'
);

let assignmentMethod = 'Speciality + Load Balance';

if (pool.length === 0) {
  pool = agents.filter(a =>
    a.speciality === 'General' && a.status === 'Available'
  );
  assignmentMethod = 'General Fallback + Load Balance';
}

if (pool.length === 0) {
  pool = agents.filter(a => a.status === 'Available');
  assignmentMethod = 'Load Balance Only';
}

const assignmentId = `assign-${Date.now()}`;
const baseUrl = config.N8N_WEBHOOK_BASE_URL || 'http://localhost:5678';

if (pool.length === 0) {
  return [{
    json: {
      ...lead,
      ...parsed,
      agentFound:       false,
      assignmentId,
      assignmentMethod: 'No agents available',
      ackUrl:           null,
      config
    }
  }];
}

// Load balance — fewest active leads wins
const selected = pool.reduce((min, a) =>
  parseInt(a.activeLeads || 0) < parseInt(min.activeLeads || 0) ? a : min
, pool[0]);

// Build acknowledgement URL
const ackUrl = `${baseUrl}/webhook/acknowledge-lead?assignmentId=${assignmentId}&agentId=${encodeURIComponent(selected.agentId)}`;

// Build HTML email for agent
function escapeHtml(text) {
  if (!text) return 'N/A';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const scoreEmoji = parsed.score === 'Hot' ? '🔥'
  : parsed.score === 'Warm' ? '📋' : '❄️';

const agentEmailHtml = `
  <div style="font-family:Arial,sans-serif;max-width:600px;color:#333;">
    <div style="background:#1a1a2e;color:white;padding:20px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">🏠 New Lead Assigned — ${escapeHtml(lead.leadName)}</h2>
    </div>
    <div style="padding:20px;background:white;border:1px solid #eee;">
      <p><strong>Lead Profile:</strong></p>
      <p>
        <strong>Name:</strong> ${escapeHtml(lead.leadName)}<br>
        <strong>Email:</strong> ${escapeHtml(lead.leadEmail)}<br>
        <strong>Phone:</strong> ${escapeHtml(lead.leadPhone)}<br>
        <strong>Intent:</strong> ${escapeHtml(lead.intent)}<br>
        <strong>Budget:</strong> ${escapeHtml(lead.budget)}<br>
        <strong>Timeline:</strong> ${escapeHtml(lead.timeline)}<br>
        <strong>Source:</strong> ${escapeHtml(lead.source)}
      </p>
      <p><em>${escapeHtml(lead.message)}</em></p>
      <hr>
      <p>
        <strong>AI Score:</strong> ${scoreEmoji} ${escapeHtml(parsed.score)}<br>
        <strong>Reasoning:</strong> ${escapeHtml(parsed.reasoning)}<br>
        <strong>Urgency:</strong> ${escapeHtml(parsed.urgencyNote)}<br>
        <strong>Opener:</strong> <em>${escapeHtml(parsed.personalisation)}</em>
      </p>
      <hr>
      <p style="font-size:13px;color:#666;">
        Assignment ID: ${assignmentId}<br>
        Method: ${assignmentMethod}<br>
        Assigned at: ${new Date().toLocaleTimeString()}
      </p>
      <p style="margin-top:20px;">
        <a href="${ackUrl}"
           style="background:#27ae60;color:white;padding:14px 28px;
           border-radius:6px;text-decoration:none;font-weight:bold;
           font-size:16px;">
          ✅ Acknowledge This Lead →
        </a>
      </p>
      <p style="font-size:12px;color:#e74c3c;margin-top:12px;">
        ⏰ You have ${config.ESCALATION_MINUTES} minutes to acknowledge 
        before this lead escalates to the broker.
      </p>
    </div>
  </div>`;

// Broker copy email HTML
const brokerEmailHtml = `
  <div style="font-family:Arial,sans-serif;max-width:600px;color:#333;">
    <p><strong>📋 Lead Assignment Copy</strong></p>
    <p>
      <strong>Lead:</strong> ${escapeHtml(lead.leadName)} 
        (${escapeHtml(lead.leadEmail)})<br>
      <strong>Score:</strong> ${scoreEmoji} ${escapeHtml(parsed.score)}<br>
      <strong>Assigned to:</strong> ${escapeHtml(selected.name)} 
        (${escapeHtml(selected.speciality)} Specialist)<br>
      <strong>Method:</strong> ${assignmentMethod}<br>
      <strong>Active leads after assignment:</strong> 
        ${parseInt(selected.activeLeads || 0) + 1}
    </p>
    <p>
      <strong>AI Reasoning:</strong> ${escapeHtml(parsed.reasoning)}
    </p>
  </div>`;

// Slack message
const slackMessage =
  `${scoreEmoji} *${parsed.score} Lead Assigned — ${lead.leadName}*\n` +
  `*Intent:* ${lead.intent} | *Budget:* ${lead.budget} | *Timeline:* ${lead.timeline}\n` +
  `*Score:* ${parsed.score} — ${parsed.reasoning}\n` +
  `*Opener:* _${parsed.personalisation}_\n` +
  `*Acknowledge:* ${ackUrl}\n` +
  `_⏰ ${config.ESCALATION_MINUTES} minutes to acknowledge_`;

return [{
  json: {
    // Lead
    leadName:      lead.leadName,
    leadEmail:     lead.leadEmail,
    leadPhone:     lead.leadPhone,
    intent:        lead.intent,
    budget:        lead.budget,
    timeline:      lead.timeline,
    message:       lead.message,
    source:        lead.source,
    leadId:        lead.leadId,
    timestamp:     lead.timestamp,
    // AI output
    score:                  parsed.score,
    reasoning:              parsed.reasoning,
    recommendedSpeciality:  parsed.recommendedSpeciality,
    urgencyNote:            parsed.urgencyNote,
    personalisation:        parsed.personalisation,
    // Assignment
    agentFound:             true,
    assignmentId,
    assignedAgentId:        selected.agentId,
    assignedAgentName:      selected.name,
    assignedAgentEmail:     selected.email,
    assignedAgentPhone:     selected.phone,
    assignedAgentSlackId:   selected.slackUserId,
    assignmentMethod,
    ackUrl,
    // Emails
    agentEmailHtml,
    brokerEmailHtml,
    slackMessage,
    // Config
    config
  }
}];

const agentId = $('Parse AI Output & Select Agent').first().json.assignedAgentId;
const agents = JSON.parse(
  $('Set: Brokerage Configuration').first().json.AGENTS_JSON
);
const agent = agents.find(a => a.agentId === agentId);
const newCount = parseInt(agent?.activeLeads || 0) + 1;
const totalAssigned = parseInt(agent?.['Total Assigned'] || 0) + 1;

return [{
  json: {
    agentId,
    newActiveLeads: String(newCount),
    newTotalAssigned: String(totalAssigned)
  }
}];

const data   = $('Parse AI Output & Select Agent').first().json;
const config = $('Set: Brokerage Configuration').first().json;

return [{
  json: {
    contactBody: JSON.stringify({
      name:  data.leadName,
      email: [{ value: data.leadEmail, primary: true }],
      phone: [{ value: data.leadPhone, primary: true }]
    }),
    pipedriveToken:  config.PIPEDRIVE_API_TOKEN,
    pipedriveDomain: config.PIPEDRIVE_DOMAIN
  }
}];

const data      = $('Parse AI Output & Select Agent').first().json;
const personId  = $('Pipedrive: Create Contact').first().json.data?.id;
const config    = $('Set: Brokerage Configuration').first().json;

return [{
  json: {
    dealBody: JSON.stringify({
      title:     `${data.leadName} — ${data.intent} — ${data.budget}`,
      person_id: personId,
      status:    'open'
    }),
    pipedriveToken:  config.PIPEDRIVE_API_TOKEN,
    pipedriveDomain: config.PIPEDRIVE_DOMAIN,
    personId
  }
}];

const raw  = $input.first().json;
const query = raw.query || raw;

return [{
  json: {
    assignmentId:  query.assignmentId  || null,
    agentId:       query.agentId       || null,
    acknowledgedAt: new Date().toISOString()
  }
}];

const ackData  = $('Extract Assignment Details').first().json;
const allRows  = $input.all().map(i => i.json);

const assignment = allRows.find(row =>
  String(row['Assignment ID'] || '').trim() ===
  String(ackData.assignmentId || '').trim()
);

if (!assignment) {
  return [{ json: { ...ackData, responseMinutes: null, agentName: 'Unknown' } }];
}

const assigned = new Date(assignment['Timestamp']);
const acked    = new Date(ackData.acknowledgedAt);
const diffMs   = acked - assigned;
const diffMins = Math.round(diffMs / 60000);

return [{
  json: {
    ...ackData,
    responseMinutes:   diffMins,
    agentName:         assignment['Assigned Agent Name'],
    assignedAgentId:   assignment['Assigned Agent ID'],
    leadName:          assignment['Lead Name']
  }
}];

const allRows  = $input.all().map(i => i.json);
const agentId  = $('Calculate Response Time').first().json.assignedAgentId;
const agent    = allRows.find(r =>
  String(r['Agent ID'] || '').trim() === String(agentId || '').trim()
);

return [{
  json: {
    agentEmail: agent?.['Email'] || null,
    agentName:  agent?.['Agent Name'] || 'Agent',
    leadName:   $('Calculate Response Time').first().json.leadName,
    responseMinutes: $('Calculate Response Time').first().json.responseMinutes
  }
}];

const assignmentId = $('Parse AI Output & Select Agent').first().json.assignmentId;
const allRows = $input.all().map(i => i.json);

const row = allRows.find(r =>
  String(r['Assignment ID'] || '').trim() ===
  String(assignmentId || '').trim()
);

return [{
  json: {
    assignmentId,
    acknowledged: row?.['Acknowledged'] === 'true' || row?.['Acknowledged'] === true,
    agentName:    row?.['Assigned Agent Name'] || 'Unknown',
    leadName:     row?.['Lead Name'] || 'Unknown',
    leadEmail:    row?.['Email'] || '',
    score:        row?.['AI Score'] || 'Unknown'
  }
}];

const config = $('Set: Section D Configuration').first().json;
const allRows = $input.all().map(i => i.json);

// Get this week's range (Mon–Sun)

const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const weekStart    = sevenDaysAgo.toISOString().substring(0, 10);

const thisWeek = allRows.filter(row => {
  const ts = String(row['Timestamp'] || '');
  if (!ts) return false;
  return ts >= weekStart;
});

if (thisWeek.length === 0) {
  return [{
    json: {
      hasAssignments: false,
      weekStart,
      digestHtml: '',
      digestSubject: ''
    }
  }];
}

function escapeHtml(text) {
  if (!text) return 'N/A';
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

// Group by agent
const byAgent = {};
for (const row of thisWeek) {
  const name = row['Assigned Agent Name'] || 'Unassigned';
  if (!byAgent[name]) {
    byAgent[name] = {
      total: 0, acknowledged: 0,
      hot: 0, warm: 0, cold: 0,
      responseTimes: [], escalated: 0
    };
  }
  const a = byAgent[name];
  a.total++;
  if (row['Acknowledged'] === 'true' || row['Acknowledged'] === true) {
    a.acknowledged++;
    if (row['Response Time (mins)']) {
      a.responseTimes.push(parseFloat(row['Response Time (mins)']));
    }
  }
  if (row['Escalated'] === 'true' || row['Escalated'] === true) a.escalated++;
  const score = String(row['AI Score'] || '').toLowerCase();
  if (score === 'hot')  a.hot++;
  else if (score === 'warm') a.warm++;
  else a.cold++;
}

// Build agent rows HTML
let agentRowsHtml = '';
for (const [agentName, stats] of Object.entries(byAgent)) {
  const avgResponse = stats.responseTimes.length > 0
    ? Math.round(stats.responseTimes.reduce((s, t) => s + t, 0) / stats.responseTimes.length)
    : null;

  agentRowsHtml += `
    <tr style="border-bottom:1px solid #eee;">
      <td style="padding:10px 8px;"><strong>${escapeHtml(agentName)}</strong></td>
      <td style="padding:10px 8px;text-align:center;">${stats.total}</td>
      <td style="padding:10px 8px;text-align:center;">${stats.acknowledged}</td>
      <td style="padding:10px 8px;text-align:center;">
        ${avgResponse !== null ? avgResponse + ' mins' : '—'}
      </td>
      <td style="padding:10px 8px;text-align:center;">
        <span style="color:#e74c3c;">🔥${stats.hot}</span> 
        <span style="color:#f39c12;"> 📋${stats.warm}</span>
        <span style="color:#95a5a6;"> ❄️${stats.cold}</span>
      </td>
      <td style="padding:10px 8px;text-align:center;">
        ${stats.escalated > 0
          ? `<span style="color:#e74c3c;">⚠️ ${stats.escalated}</span>`
          : '✅ 0'}
      </td>
    </tr>`;
}

// Team totals
const teamAcked     = thisWeek.filter(r =>
  r['Acknowledged'] === 'true' || r['Acknowledged'] === true).length;
const teamEscalated = thisWeek.filter(r =>
  r['Escalated'] === 'true' || r['Escalated'] === true).length;
const allTimes      = thisWeek
  .filter(r => r['Response Time (mins)'])
  .map(r => parseFloat(r['Response Time (mins)']));
const avgTeamTime   = allTimes.length > 0
  ? Math.round(allTimes.reduce((s, t) => s + t, 0) / allTimes.length)
  : null;
const hotCount  = thisWeek.filter(r =>
  String(r['AI Score'] || '').toLowerCase() === 'hot').length;
const warmCount = thisWeek.filter(r =>
  String(r['AI Score'] || '').toLowerCase() === 'warm').length;
const coldCount = thisWeek.filter(r =>
  String(r['AI Score'] || '').toLowerCase() === 'cold').length;

const digestHtml = `
  <div style="font-family:Arial,sans-serif;max-width:750px;margin:0 auto;color:#333;">
    <div style="background:#1a1a2e;color:white;padding:24px;border-radius:8px 8px 0 0;">
      <h2 style="margin:0;">📊 Weekly Lead Performance Report</h2>
      <p style="margin:8px 0 0 0;opacity:0.8;">
        Week of ${new Date(weekStart).toLocaleDateString('en-US',
          { month: 'long', day: 'numeric', year: 'numeric' })}
      </p>
    </div>
    <div style="background:#f8f9fa;padding:14px 24px;border-bottom:1px solid #ddd;">
      <p style="margin:0;font-size:14px;">
        Total leads: <strong>${thisWeek.length}</strong> &nbsp;|&nbsp;
        🔥 Hot: <strong>${hotCount}</strong> &nbsp;|&nbsp;
        📋 Warm: <strong>${warmCount}</strong> &nbsp;|&nbsp;
        ❄️ Cold: <strong>${coldCount}</strong> &nbsp;|&nbsp;
        Avg response: <strong>${avgTeamTime !== null ? avgTeamTime + ' mins' : 'N/A'}</strong> &nbsp;|&nbsp;
        Escalations: <strong style="color:${teamEscalated > 0 ? '#e74c3c' : '#27ae60'}">
          ${teamEscalated}
        </strong>
      </p>
    </div>
    <div style="padding:24px;background:white;">
      <h3 style="margin:0 0 16px 0;color:#1a1a2e;">Agent Breakdown</h3>
      <table style="width:100%;border-collapse:collapse;font-size:14px;">
        <thead>
          <tr style="background:#f8f9fa;">
            <th style="padding:10px 8px;text-align:left;">Agent</th>
            <th style="padding:10px 8px;text-align:center;">Assigned</th>
            <th style="padding:10px 8px;text-align:center;">Acknowledged</th>
            <th style="padding:10px 8px;text-align:center;">Avg Response</th>
            <th style="padding:10px 8px;text-align:center;">By Score</th>
            <th style="padding:10px 8px;text-align:center;">Escalations</th>
          </tr>
        </thead>
        <tbody>${agentRowsHtml}</tbody>
      </table>
    </div>
    <div style="background:#f8f9fa;padding:16px 24px;
      border-radius:0 0 8px 8px;border-top:1px solid #ddd;
      font-size:12px;color:#888;">
      Powered by QualMatic AI | Brokerage Lead Router
    </div>
  </div>`;

return [{
  json: {
    digestHtml,
    digestSubject: `📊 Weekly lead report — ${thisWeek.length} leads, ${teamEscalated} escalations`,
    hasAssignments: true,
    totalLeads:     thisWeek.length,
    escalations:    teamEscalated,
    weekStart
  }
}];
